import{_ as l,o as a,c as i,a0 as o}from"./chunks/framework.DCToIpx6.js";const m=JSON.parse('{"title":"dynamic-column-config Specification","description":"","frontmatter":{},"headers":[],"relativePath":"specs/dynamic-column-config/spec.md","filePath":"specs/dynamic-column-config/spec.md"}'),c={name:"specs/dynamic-column-config/spec.md"};function t(n,e,r,d,s,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="dynamic-column-config-specification" tabindex="-1">dynamic-column-config Specification <a class="header-anchor" href="#dynamic-column-config-specification" aria-label="Permalink to &quot;dynamic-column-config Specification&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Define column-level configuration properties (<code>visible</code>, <code>tooltip</code>, <code>clickeable</code>, <code>filterable</code>) that control rendering, interaction, and filter behavior for the <code>GenericTableWithoutActionsComponent</code> in Angular 14 + Material 14.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><h3 id="requirement-column-visibility" tabindex="-1">Requirement: Column Visibility <a class="header-anchor" href="#requirement-column-visibility" aria-label="Permalink to &quot;Requirement: Column Visibility&quot;">​</a></h3><p>The table MUST exclude columns with <code>visible: false</code> from the rendered DOM. Columns where <code>visible</code> is <code>undefined</code> or <code>true</code> MUST render normally. Columns with <code>detail: true</code> SHOULD also be <code>visible: false</code> — their data is preserved for emission but not rendered.</p><h4 id="scenario-column-with-visible-false-is-excluded" tabindex="-1">Scenario: Column with visible: false is excluded <a class="header-anchor" href="#scenario-column-with-visible-false-is-excluded" aria-label="Permalink to &quot;Scenario: Column with visible: false is excluded&quot;">​</a></h4><ul><li>GIVEN a table with columns <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}, {key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}]</code></li><li>WHEN the table renders</li><li>THEN only the <code>name</code> column appears in the rendered DOM</li><li>AND the <code>secret</code> column is absent (not merely hidden via CSS)</li></ul><h4 id="scenario-column-with-undefined-visible-renders" tabindex="-1">Scenario: Column with undefined visible renders <a class="header-anchor" href="#scenario-column-with-undefined-visible-renders" aria-label="Permalink to &quot;Scenario: Column with undefined visible renders&quot;">​</a></h4><ul><li>GIVEN a column with no <code>visible</code> property set</li><li>WHEN the table renders</li><li>THEN that column appears in the rendered DOM</li></ul><h3 id="requirement-cell-tooltip" tabindex="-1">Requirement: Cell Tooltip <a class="header-anchor" href="#requirement-cell-tooltip" aria-label="Permalink to &quot;Requirement: Cell Tooltip&quot;">​</a></h3><p>When a column has a <code>tooltip</code> string, cells in that column MUST display a Material tooltip (<code>matTooltip</code>) on hover. Columns without <code>tooltip</code> MUST NOT show any tooltip.</p><h4 id="scenario-tooltip-appears-on-cell-hover" tabindex="-1">Scenario: Tooltip appears on cell hover <a class="header-anchor" href="#scenario-tooltip-appears-on-cell-hover" aria-label="Permalink to &quot;Scenario: Tooltip appears on cell hover&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;email&#39;, header: &#39;Email&#39;, tooltip: &#39;Click to copy&#39;}</code></li><li>WHEN the user hovers over a cell in that column</li><li>THEN a Material tooltip with text &quot;Click to copy&quot; appears</li></ul><h4 id="scenario-column-without-tooltip-shows-none" tabindex="-1">Scenario: Column without tooltip shows none <a class="header-anchor" href="#scenario-column-without-tooltip-shows-none" aria-label="Permalink to &quot;Scenario: Column without tooltip shows none&quot;">​</a></h4><ul><li>GIVEN a column with no <code>tooltip</code> property</li><li>WHEN the user hovers over a cell in that column</li><li>THEN no tooltip appears</li></ul><h3 id="requirement-clickable-cells" tabindex="-1">Requirement: Clickable Cells <a class="header-anchor" href="#requirement-clickable-cells" aria-label="Permalink to &quot;Requirement: Clickable Cells&quot;">​</a></h3><p>When a column has <code>clickeable: true</code>, clicking a cell MUST emit a <code>cellClick</code> event with payload <code>{ column: TableColumn; row: any; detailData?: {label: string, value: any}[] }</code>. The component MUST NOT handle the action itself — it delegates to the parent. When detail columns exist, their values are included in <code>detailData</code>.</p><h4 id="scenario-clickable-cell-emits-cellclick-with-detaildata" tabindex="-1">Scenario: Clickable cell emits cellClick with detailData <a class="header-anchor" href="#scenario-clickable-cell-emits-cellclick-with-detaildata" aria-label="Permalink to &quot;Scenario: Clickable cell emits cellClick with detailData&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;name&#39;, header: &#39;Name&#39;, clickeable: true}</code></li><li>AND a detail column <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code></li><li>AND a row <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code></li><li>WHEN the user clicks the &quot;Alice&quot; cell</li><li>THEN <code>cellClick</code> payload includes <code>detailData: [{label: &#39;ID&#39;, value: &#39;42&#39;}]</code></li></ul><h4 id="scenario-non-clickable-cell-emits-nothing" tabindex="-1">Scenario: Non-clickable cell emits nothing <a class="header-anchor" href="#scenario-non-clickable-cell-emits-nothing" aria-label="Permalink to &quot;Scenario: Non-clickable cell emits nothing&quot;">​</a></h4><ul><li>GIVEN a column without <code>clickeable</code> or with <code>clickeable: false</code></li><li>WHEN the user clicks a cell in that column</li><li>THEN no <code>cellClick</code> event is emitted</li></ul><h3 id="requirement-filterable-columns" tabindex="-1">Requirement: Filterable Columns <a class="header-anchor" href="#requirement-filterable-columns" aria-label="Permalink to &quot;Requirement: Filterable Columns&quot;">​</a></h3><p>The global filter MUST search only columns where <code>filterable !== false</code>. Columns with <code>filterable: false</code> MUST be excluded from search. When <code>filterable</code> is <code>undefined</code>, the column MUST default to included (searchable).</p><h4 id="scenario-filterable-false-excludes-column-from-search" tabindex="-1">Scenario: Filterable: false excludes column from search <a class="header-anchor" href="#scenario-filterable-false-excludes-column-from-search" aria-label="Permalink to &quot;Scenario: Filterable: false excludes column from search&quot;">​</a></h4><ul><li>GIVEN columns <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}, {key: &#39;notes&#39;, header: &#39;Notes&#39;, filterable: false}]</code></li><li>AND rows <code>[{name: &#39;Alice&#39;, notes: &#39;confidential&#39;}]</code></li><li>WHEN the user types &quot;confidential&quot; in the global filter</li><li>THEN no rows are shown (the note column was excluded from the search)</li></ul><h4 id="scenario-filterable-undefined-includes-column" tabindex="-1">Scenario: Filterable undefined includes column <a class="header-anchor" href="#scenario-filterable-undefined-includes-column" aria-label="Permalink to &quot;Scenario: Filterable undefined includes column&quot;">​</a></h4><ul><li>GIVEN columns with no <code>filterable</code> property</li><li>WHEN the user types a search term in the global filter</li><li>THEN all columns are searched (backward-compatible default)</li></ul><h3 id="requirement-backward-compatibility" tabindex="-1">Requirement: Backward Compatibility <a class="header-anchor" href="#requirement-backward-compatibility" aria-label="Permalink to &quot;Requirement: Backward Compatibility&quot;">​</a></h3><p>Existing consumers that do not pass the new properties MUST continue to work identically — all columns render, no tooltips appear, clicking cells has no effect, and the global filter searches every column.</p><h4 id="scenario-legacy-config-renders-identically" tabindex="-1">Scenario: Legacy config renders identically <a class="header-anchor" href="#scenario-legacy-config-renders-identically" aria-label="Permalink to &quot;Scenario: Legacy config renders identically&quot;">​</a></h4><ul><li>GIVEN a table component with a legacy columns array <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}]</code></li><li>WHEN the component initializes</li><li>THEN all columns render normally</li><li>AND no tooltips appear on cell hover</li><li>AND clicking cells has no effect</li><li>AND the global filter searches all columns</li></ul><h3 id="requirement-detail-property" tabindex="-1">Requirement: Detail Property <a class="header-anchor" href="#requirement-detail-property" aria-label="Permalink to &quot;Requirement: Detail Property&quot;">​</a></h3><p>Columns MAY specify <code>detail: boolean</code> to mark them as carriers of invisible data. A column with <code>detail: true</code> MUST have its row value preserved for emission on cell click, even when <code>visible: false</code>.</p><h4 id="scenario-detail-column-carries-invisible-data-on-click" tabindex="-1">Scenario: Detail column carries invisible data on click <a class="header-anchor" href="#scenario-detail-column-carries-invisible-data-on-click" aria-label="Permalink to &quot;Scenario: Detail column carries invisible data on click&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code> and a row <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code></li><li>WHEN a clickable cell in that row is clicked</li><li>THEN the <code>cellClick</code> payload includes <code>{label: &#39;ID&#39;, value: &#39;42&#39;}</code> in <code>detailData</code></li></ul><h4 id="scenario-non-detail-invisible-column-excluded-from-emission" tabindex="-1">Scenario: Non-detail invisible column excluded from emission <a class="header-anchor" href="#scenario-non-detail-invisible-column-excluded-from-emission" aria-label="Permalink to &quot;Scenario: Non-detail invisible column excluded from emission&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}</code> without <code>detail: true</code></li><li>WHEN a clickable cell in that row is clicked</li><li>THEN <code>secret</code> MUST NOT appear in <code>detailData</code></li></ul><h3 id="requirement-detail-data-emission" tabindex="-1">Requirement: Detail Data Emission <a class="header-anchor" href="#requirement-detail-data-emission" aria-label="Permalink to &quot;Requirement: Detail Data Emission&quot;">​</a></h3><p>When a <code>clickeable</code> cell is clicked, the component MUST collect all columns where <code>detail: true</code> from that row and append them as <code>detailData</code> in the <code>cellClick</code> payload.</p><h4 id="scenario-multiple-detail-columns-emit-all-values" tabindex="-1">Scenario: Multiple detail columns emit all values <a class="header-anchor" href="#scenario-multiple-detail-columns-emit-all-values" aria-label="Permalink to &quot;Scenario: Multiple detail columns emit all values&quot;">​</a></h4><ul><li>GIVEN columns with <code>key: &#39;orderId&#39;, detail: true</code> and <code>key: &#39;market&#39;, detail: true</code></li><li>AND a row <code>{name: &#39;Alice&#39;, orderId: &#39;ORD-123&#39;, market: &#39;NYSE&#39;}</code></li><li>WHEN the user clicks a clickable cell in that row</li><li>THEN <code>detailData</code> contains two entries with labels &quot;Order ID&quot; and &quot;Market&quot;</li></ul><h4 id="scenario-no-detail-columns-emits-empty-array" tabindex="-1">Scenario: No detail columns emits empty array <a class="header-anchor" href="#scenario-no-detail-columns-emits-empty-array" aria-label="Permalink to &quot;Scenario: No detail columns emits empty array&quot;">​</a></h4><ul><li>GIVEN columns without any <code>detail: true</code></li><li>WHEN a clickable cell is clicked</li><li>THEN <code>cellClick.detailData</code> is <code>[]</code></li></ul><h3 id="requirement-detail-data-format" tabindex="-1">Requirement: Detail Data Format <a class="header-anchor" href="#requirement-detail-data-format" aria-label="Permalink to &quot;Requirement: Detail Data Format&quot;">​</a></h3><p>The <code>detailData</code> field SHOULD be an array of <code>{label: string; value: any}</code> objects. <code>label</code> MUST match the column <code>header</code> and <code>value</code> MUST match the row field value.</p><h4 id="scenario-detaildata-follows-label-value-contract" tabindex="-1">Scenario: detailData follows label/value contract <a class="header-anchor" href="#scenario-detaildata-follows-label-value-contract" aria-label="Permalink to &quot;Scenario: detailData follows label/value contract&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;code&#39;, header: &#39;Code&#39;, detail: true}</code> and a row with <code>code: &#39;ABC&#39;</code></li><li>WHEN a clickable cell is clicked</li><li>THEN <code>detailData[0]</code> equals <code>{label: &#39;Code&#39;, value: &#39;ABC&#39;}</code></li></ul>',48)])])}const b=l(c,[["render",t]]);export{m as __pageData,b as default};
